1	#ifndef SG_FUSED_SM90_MODEL_STAGES_DECODER_CUH_
2	#define SG_FUSED_SM90_MODEL_STAGES_DECODER_CUH_
3	// ============================================================================
4	// csrc/fused/sm_90/model_stages_decoder.cuh — PHASE 1 of the TRUE L3 fused
5	// megakernel: the REAL transformer-decoder forward + backward as in-kernel
6	// stages of the persistent megakernel (replaces the element-local SURROGATE in
7	// model_stages.cuh for the (transformer_decoder × adamw) cell).
8	//
9	// HONESTY: this is the genuine eager architecture (grokking_race_v2.py
10	// _raw_model → Transformer), transcribed LINE-FOR-LINE from the verified
11	// PyTorch oracle in tests/hw/decoder_oracle.py, which is asserted bit-identical
12	// (fp64, ~1e-15 rel) to torch.autograd for the loss and EVERY one of the 30
13	// parameter gradients. There is NO placeholder math on this path. The one
14	// deliberate, documented deviation from the oracle is execution mechanics, not
15	// numerics: the backward RECOMPUTES each layer's forward from the cached layer
16	// INPUT (rather than caching every intermediate) to keep only one layer's
17	// activations live in smem at a time — see the smem-budget note below. The math
18	// computed is identical; only the storage strategy differs.
19	//
20	// ARCHITECTURE (exact; cites grokking_race_v2.py lines):
21	//   Transformer(nl=2, d=128, h=4, ntok=99, seq=4)  [_raw_model hardcodes seq=4]
22	//     tok = Embedding(99,128) (:360) + pos = Embedding(4,128) (:360)
23	//     2 × DecoderBlock (:346):
24	//       attn = MultiheadAttention(128,4,batch_first) (:349), causal mask
25	//              triu(diag=1) (:352): pos i attends j<=i
26	//       n1,n2 = LayerNorm(128) (:350), eps=1e-5 (torch default)
27	//       ff = Linear(128,512) → GELU(exact erf) → Linear(512,128) (:351)
28	//       POST-LN: x=n1(x+attn(x)); h=n2(x+ff(x))  (:354-355)
29	//     norm = LayerNorm(128) (:362); out = Linear(128,99) (:362)
30	//     forward: h=tok+pos; for l: h=l(h); return out(norm(h)[:,-1,:]) (:366-368)
31	//   loss = cross_entropy(logits, targets) (mean over batch; :745).
32	//
33	// NUMERICS (verified in the oracle; see decoder_oracle.py):
34	//   * GELU = exact erf  0.5x(1+erf(x/√2)); grad 0.5(1+erf(x/√2))+x·φ(x),
35	//     φ(x)=(1/√(2π))e^{-x²/2}.  (The surrogate's tanh approx is ~4e-4 off and
36	//     would blow the 1e-4 grad tolerance — NOT used here.)
37	//   * LayerNorm eps = 1e-5; dx uses the two mean-correction terms.
38	//   * attention scale 1/√dh = 1/√32; softmax subtracts the row max.
39	//   * cross-entropy MEAN over B → dlogits = (softmax−onehot)/B.
40	//
41	// PARALLELIZATION (locked design — Option B, batch-parallel, deterministic):
42	//   * Each CTA owns a FIXED contiguous batch slice (by blockIdx.x — NOT the
43	//     work-stealing task queue, which is param-tensor-parallel and would vary
44	//     the batch→CTA grouping; fp32 sums are not associative so a varying
45	//     grouping is non-deterministic). The whole CTA cooperates on ONE sample at
46	//     a time and iterates its slice SEQUENTIALLY.
47	//   * Per-sample, the CTA accumulates that sample's weight-grad contribution
48	//     into the CTA's OWN partial buffer in the global workspace
49	//     (gw + cta*total). Each dW element has a SINGLE owner thread that does
50	//     partial[e] += contrib across the slice's samples in fixed order
51	//     (__syncthreads between samples) — single-writer, no atomics, deterministic.
52	//   * One grid barrier, then a deterministic cross-CTA reduce: sum
53	//     partial[0..nCTA) in ASCENDING CTA index into the global grad buffer
54	//     (determinism lives in the per-element summation ORDER, not who computes it
55	//     — so the reduce REUSES the work-steal queue: whichever CTA grabs a param
56	//     element-range sums the partials for it in ascending CTA order).
57	//   * Another grid barrier, then the existing apply_optimizer<AdamW> tail
58	//     consumes the reduced grad in place.
59	//   * Loss: each CTA sums its slice's NLL (fp32) into a per-CTA loss slot; the
60	//     reduce sums those in fp64 and divides by B → one device float (the 1e-5
61	//     loss rel-tol is the tightest gate; fp32 atomic-summing 4191 terms misses it).
62	//
63	// SMEM BUDGET PER CTA (one sample, one layer live; recompute-in-backward):
64	//   The dominant per-sample buffer is the FFN hidden ff0/g [S=4 × 4d=512] =
65	//   2048 floats = 8 KB. With the QKV [4×384], ctx/x1/residual [4×128] and the LN
66	//   caches, one layer's live working set is ~25 KB — UNDER the 48 KB static-smem
67	//   cliff, so NO dynamic-smem opt-in is needed and the occupancy≥1 launch guard
68	//   in fused_megakernel.cuh (dynamicSMemBytes=0) is unchanged. Caching BOTH
69	//   layers (~50 KB) would cross 48 KB and force cudaFuncSetAttribute — avoided by
70	//   the per-layer recompute. The flat smem arena below is sized accordingly.
71	// ============================================================================
72	
73	#include "csrc/fused/megakernel_common.cuh"
74	#include "csrc/fused/sm_90/decoder_layout.cuh"
75	#include <cuda_runtime.h>
76	#include <cstdint>
77	#include <math_constants.h>
78	
79	namespace sg { namespace fused { namespace sm90 {
80	
81	// ── Decoder compile-time shape constants (mirror tests/hw/decoder_oracle.py and
82	//    csrc/fused/sm_90/decoder_layout.cuh; static_asserts there guard the count
83	//    + total against named_parameters()). ─────────────────────────────────────
84	namespace dec {
85	constexpr int kVocab  = SG_DEC_VOCAB;   // 99
86	constexpr int kD      = SG_DEC_D;       // 128
87	constexpr int kHeads  = SG_DEC_HEADS;   // 4
88	constexpr int kLayers = SG_DEC_LAYERS;  // 2
89	constexpr int kSeq    = SG_DEC_SEQ;     // 4
90	constexpr int kDff    = SG_DEC_DFF;     // 512
91	constexpr int kDhead  = kD / kHeads;    // 32
92	constexpr float kLnEps = 1e-5f;         // torch LayerNorm default
93	// Attention scale 1/sqrt(dhead). rsqrtf is fine; keep it a constexpr-ish value
94	// computed once on host-visible compile (1/sqrt(32)).
95	__device__ __forceinline__ float attn_scale() { return rsqrtf((float)kDhead); }
96	}  // namespace dec
97	
98	// ── Exact-erf GELU + derivative (the real nn.GELU(), NOT the tanh surrogate). ──
99	__device__ __forceinline__ float dec_gelu(float x) {
100	    // 0.5 x (1 + erf(x/sqrt2)).  M_SQRT1_2 = 1/sqrt(2).
101	    return 0.5f * x * (1.0f + erff(x * (float)M_SQRT1_2));
102	}
103	__device__ __forceinline__ float dec_gelu_grad(float x) {
104	    // 0.5(1+erf(x/√2)) + x · φ(x), φ(x) = (1/√(2π)) e^{-x²/2}.
105	    const float cdf = 0.5f * (1.0f + erff(x * (float)M_SQRT1_2));
106	    const float inv_sqrt_2pi = 0.39894228040143270286f;  // 1/sqrt(2*pi)
107	    const float pdf = inv_sqrt_2pi * __expf(-0.5f * x * x);
108	    return cdf + x * pdf;
109	}
110	
111	// ── Per-CTA scratch for one sample. POD held in smem (one instance per CTA).
112	//    Sizes chosen so the live set is one layer (recompute in backward). The
113	//    arrays that must survive fwd→bwd within a layer are kept; the rest are
114	//    recomputed. All [kSeq × width] row-major (row = position). ───────────────
115	struct DecSampleSmem {
116	    // Per-layer cached INPUT to each layer (h before the layer) — the only
117	    // cross-layer state kept, so the backward can recompute each layer's fwd.
118	    float layer_in[dec::kLayers][dec::kSeq][dec::kD];   // 2*4*128 = 1024 f
119	    // The final-norm input (last layer output, all positions) for bwd.
120	    float final_in[dec::kSeq][dec::kD];                 // 4*128 = 512 f
121	    // Scratch reused within a single layer's fwd or bwd (one layer live):
122	    float qkv[dec::kSeq][3 * dec::kD];                  // 4*384 = 1536 f
123	    float ctx[dec::kSeq][dec::kD];                      // 4*128 = 512 f
124	    float x1[dec::kSeq][dec::kD];                       // 4*128 = 512 f (post n1)
125	    float ff0[dec::kSeq][dec::kDff];                    // 4*512 = 2048 f (pre-gelu)
126	    float gact[dec::kSeq][dec::kDff];                   // 4*512 = 2048 f (post-gelu)
127	    float attn[dec::kHeads][dec::kSeq][dec::kSeq];      // 4*4*4 = 64 f
128	    // LayerNorm caches (xhat + inv_std) for n1, n2, final — per position.
129	    float n1_xhat[dec::kSeq][dec::kD];
130	    float n1_inv[dec::kSeq];
131	    float n2_xhat[dec::kSeq][dec::kD];
132	    float n2_inv[dec::kSeq];
133	    float fn_xhat[dec::kSeq][dec::kD];
134	    float fn_inv[dec::kSeq];
135	    // Backward adjoints carried across sub-steps (one layer live), per position.
136	    float dh[dec::kSeq][dec::kD];                       // running grad wrt block out
137	    float logits[dec::kVocab];                          // last-pos logits (bwd)
138	    // Dedicated attention-backward dscores buffer (NOT aliased over `attn`, so
139	    // the forward softmax weights stay live while dv/dq/dk read them). 64 f.
140	    float dsc[dec::kHeads][dec::kSeq][dec::kSeq];
141	    // Reductions across threads for row stats (mean / max / dot). 256 threads.
142	    float red[256];
143	};
144	
145	// A typed view over the flat weight blob using the generated offsets. All
146	// pointers are into the single global `params` buffer (read-only in fwd/bwd).
147	struct DecWeights {
148	    const float* tok;     // [kVocab, kD]
149	    const float* pos;     // [kSeq, kD]
150	    struct Layer {
151	        const float* in_w;   // [3d, d]
152	        const float* in_b;   // [3d]
153	        const float* out_w;  // [d, d]
154	        const float* out_b;  // [d]
155	        const float* n1_w;   // [d]
156	        const float* n1_b;   // [d]
157	        const float* n2_w;   // [d]
158	        const float* n2_b;   // [d]
159	        const float* ff0_w;  // [4d, d]
160	        const float* ff0_b;  // [4d]
161	        const float* ff2_w;  // [d, 4d]
162	        const float* ff2_b;  // [d]
163	    } layer[dec::kLayers];
164	    const float* norm_w;  // [d]
165	    const float* norm_b;  // [d]
166	    const float* out_w;   // [kVocab, d]
167	    const float* out_b;   // [kVocab]
168	};
169	
170	// Bind DecWeights to the flat params using the generated element offsets. The
171	// offsets array (csrc/fused/sm_90/decoder_layout.cuh::kDecOffsets) is the C++
172	// mirror of tests/hw/decoder_oracle.py::decoder_param_layout(), static-asserted.
173	__device__ __forceinline__ DecWeights dec_bind(const float* p) {
174	    DecWeights w;
175	    int i = 0;
176	    w.tok = p + kDecOffsets[i++];
177	    w.pos = p + kDecOffsets[i++];
178	    for (int li = 0; li < dec::kLayers; ++li) {
179	        w.layer[li].in_w  = p + kDecOffsets[i++];
180	        w.layer[li].in_b  = p + kDecOffsets[i++];
181	        w.layer[li].out_w = p + kDecOffsets[i++];
182	        w.layer[li].out_b = p + kDecOffsets[i++];
183	        w.layer[li].n1_w  = p + kDecOffsets[i++];
184	        w.layer[li].n1_b  = p + kDecOffsets[i++];
185	        w.layer[li].n2_w  = p + kDecOffsets[i++];
186	        w.layer[li].n2_b  = p + kDecOffsets[i++];
187	        w.layer[li].ff0_w = p + kDecOffsets[i++];
188	        w.layer[li].ff0_b = p + kDecOffsets[i++];
189	        w.layer[li].ff2_w = p + kDecOffsets[i++];
190	        w.layer[li].ff2_b = p + kDecOffsets[i++];
191	    }
192	    w.norm_w = p + kDecOffsets[i++];
193	    w.norm_b = p + kDecOffsets[i++];
194	    w.out_w  = p + kDecOffsets[i++];
195	    w.out_b  = p + kDecOffsets[i++];
196	    return w;
197	}
198	
199	// Identical helper for the per-CTA grad PARTIAL buffer (writable, same layout).
200	struct DecGrad {
201	    float* tok; float* pos;
202	    struct Layer { float* in_w; float* in_b; float* out_w; float* out_b;
203	        float* n1_w; float* n1_b; float* n2_w; float* n2_b;
204	        float* ff0_w; float* ff0_b; float* ff2_w; float* ff2_b; } layer[dec::kLayers];
205	    float* norm_w; float* norm_b; float* out_w; float* out_b;
206	};
207	__device__ __forceinline__ DecGrad dec_bind_grad(float* p) {
208	    DecGrad w; int i = 0;
209	    w.tok = p + kDecOffsets[i++];
210	    w.pos = p + kDecOffsets[i++];
211	    for (int li = 0; li < dec::kLayers; ++li) {
212	        w.layer[li].in_w  = p + kDecOffsets[i++];
213	        w.layer[li].in_b  = p + kDecOffsets[i++];
214	        w.layer[li].out_w = p + kDecOffsets[i++];
215	        w.layer[li].out_b = p + kDecOffsets[i++];
216	        w.layer[li].n1_w  = p + kDecOffsets[i++];
217	        w.layer[li].n1_b  = p + kDecOffsets[i++];
218	        w.layer[li].n2_w  = p + kDecOffsets[i++];
219	        w.layer[li].n2_b  = p + kDecOffsets[i++];
220	        w.layer[li].ff0_w = p + kDecOffsets[i++];
221	        w.layer[li].ff0_b = p + kDecOffsets[i++];
222	        w.layer[li].ff2_w = p + kDecOffsets[i++];
223	        w.layer[li].ff2_b = p + kDecOffsets[i++];
224	    }
225	    w.norm_w = p + kDecOffsets[i++];
226	    w.norm_b = p + kDecOffsets[i++];
227	    w.out_w  = p + kDecOffsets[i++];
228	    w.out_b  = p + kDecOffsets[i++];
229	    return w;
230	}
231	
232	// ── Block-wide reductions (256 threads) over a value `v`. The smem `red` slot
233	//    is the DecSampleSmem::red array. All threads must call. ──────────────────
234	__device__ __forceinline__ float dec_block_sum(float v, float* red) {
235	    const unsigned full = 0xffffffffu;
236	    #pragma unroll
237	    for (int o = 16; o > 0; o >>= 1) v += __shfl_down_sync(full, v, o);
238	    const int lane = threadIdx.x & 31, warp = threadIdx.x >> 5;
239	    if (lane == 0) red[warp] = v;
240	    __syncthreads();
241	    const int nwarp = (blockDim.x + 31) >> 5;
242	    float r = 0.0f;
243	    if (warp == 0) {
244	        float p = (lane < nwarp) ? red[lane] : 0.0f;
245	        #pragma unroll
246	        for (int o = 16; o > 0; o >>= 1) p += __shfl_down_sync(full, p, o);
247	        if (lane == 0) red[0] = p;
248	    }
249	    __syncthreads();
250	    r = red[0];
251	    __syncthreads();
252	    return r;
253	}
254	__device__ __forceinline__ float dec_block_max(float v, float* red) {
255	    const unsigned full = 0xffffffffu;
256	    #pragma unroll
257	    for (int o = 16; o > 0; o >>= 1) {
258	        float other = __shfl_down_sync(full, v, o);
259	        v = fmaxf(v, other);
260	    }
261	    const int lane = threadIdx.x & 31, warp = threadIdx.x >> 5;
262	    if (lane == 0) red[warp] = v;
263	    __syncthreads();
264	    const int nwarp = (blockDim.x + 31) >> 5;
265	    float r;
266	    if (warp == 0) {
267	        float p = (lane < nwarp) ? red[lane] : -CUDART_INF_F;
268	        #pragma unroll
269	        for (int o = 16; o > 0; o >>= 1) {
270	            float other = __shfl_down_sync(full, p, o);
271	            p = fmaxf(p, other);
272	        }
273	        if (lane == 0) red[0] = p;
274	    }
275	    __syncthreads();
276	    r = red[0];
277	    __syncthreads();
278	    return r;
279	}
280	
281	// ────────────────────────────────────────────────────────────────────────────
282	//  Primitive in-kernel ops, CTA-cooperative over one sample. Inputs/outputs are
283	//  smem [kSeq, width] tiles. Threads stride over the (position, feature) grid.
284	//  These mirror the oracle's primitive ops exactly.
285	// ────────────────────────────────────────────────────────────────────────────
286	
287	// y[s, :out] = x[s, :in] @ W[out, in]^T + b[out].  W row-major [out, in].
288	// CTA-cooperative: one thread per (s, o) output element, strided.
289	__device__ __forceinline__ void dec_linear(
290	        const float* __restrict__ x, int in_dim,
291	        const float* __restrict__ W, const float* __restrict__ b, int out_dim,
292	        float* __restrict__ y) {
293	    const int total = dec::kSeq * out_dim;
294	    for (int idx = threadIdx.x; idx < total; idx += blockDim.x) {
295	        const int s = idx / out_dim;
296	        const int o = idx % out_dim;
297	        const float* xr = x + s * in_dim;
298	        const float* Wr = W + (int64_t)o * in_dim;
299	        float acc = (b != nullptr) ? b[o] : 0.0f;
300	        #pragma unroll 4
301	        for (int k = 0; k < in_dim; ++k) acc += xr[k] * Wr[k];
302	        y[s * out_dim + o] = acc;
303	    }
304	    __syncthreads();
305	}
306	
307	// LayerNorm forward over the last dim (width=d). Caches xhat + inv_std for bwd.
308	// gamma/beta are [d]. Per position: mean/var across d (cooperative reduce).
309	__device__ __forceinline__ void dec_layernorm_fwd(
310	        const float* __restrict__ x, const float* __restrict__ gamma,
311	        const float* __restrict__ beta, float* __restrict__ y,
312	        float* __restrict__ xhat_out, float* __restrict__ inv_out,
313	        float* red) {
314	    // Process positions sequentially (kSeq small); each is a full-CTA reduce.
315	    for (int s = 0; s < dec::kSeq; ++s) {
316	        const float* xr = x + s * dec::kD;
317	        float sum = 0.0f;
318	        for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) sum += xr[j];
319	        float mean = dec_block_sum(sum, red) / (float)dec::kD;
320	        float vs = 0.0f;
321	        for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
322	            float c = xr[j] - mean; vs += c * c;
323	        }
324	        float var = dec_block_sum(vs, red) / (float)dec::kD;
325	        float inv = rsqrtf(var + dec::kLnEps);
326	        if (threadIdx.x == 0) inv_out[s] = inv;
327	        for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
328	            float xh = (xr[j] - mean) * inv;
329	            xhat_out[s * dec::kD + j] = xh;
330	            y[s * dec::kD + j] = xh * gamma[j] + beta[j];
331	        }
332	        __syncthreads();
333	    }
334	}
335	
336	// ────────────────────────────────────────────────────────────────────────────
337	//  FORWARD for one sample (CTA-cooperative). `tokens_s` is this sample's kSeq
338	//  token ids (smem). Writes the per-layer input cache + final-norm input +
339	//  last-position logits into `sm`, and returns the sample NLL (all threads see
340	//  the same value). Recompute-friendly: the layer-local scratch (qkv/ctx/x1/
341	//  ff0/gact/attn + LN caches) reflects the LAST layer processed; backward
342	//  recomputes per layer from layer_in.
343	// ────────────────────────────────────────────────────────────────────────────
344	__device__ float dec_forward_sample(const DecWeights& w, const int* tokens_s,
345	                                     int target, DecSampleSmem* sm) {
346	    // Embedding + positional: h0[s, j] = tok[tok_s][j] + pos[s][j].
347	    for (int idx = threadIdx.x; idx < dec::kSeq * dec::kD; idx += blockDim.x) {
348	        const int s = idx / dec::kD, j = idx % dec::kD;
349	        sm->layer_in[0][s][j] = w.tok[(int64_t)tokens_s[s] * dec::kD + j]
350	                              + w.pos[(int64_t)s * dec::kD + j];
351	    }
352	    __syncthreads();
353	
354	    for (int li = 0; li < dec::kLayers; ++li) {
355	        const DecWeights::Layer& L = w.layer[li];
356	        float* hin = &sm->layer_in[li][0][0];   // [kSeq, kD]
357	        // qkv = hin @ in_w^T + in_b  -> [kSeq, 3d]
358	        dec_linear(hin, dec::kD, L.in_w, L.in_b, 3 * dec::kD, &sm->qkv[0][0]);
359	        // Attention per head: scores = q·k^T * scale (+ causal), softmax, ctx.
360	        // q,k,v live in qkv columns [0,d),[d,2d),[2d,3d). ctx -> sm->ctx [kSeq,d].
361	        const float scale = dec::attn_scale();
362	        // One thread per (head, qpos) computes that row's softmax + ctx slice.
363	        // kSeq*kHeads = 16 rows; threads stride. Each thread loops d_head.
364	        for (int r = threadIdx.x; r < dec::kHeads * dec::kSeq; r += blockDim.x) {
365	            const int hh = r / dec::kSeq;     // head
366	            const int qi = r % dec::kSeq;     // query position
367	            const int qoff = hh * dec::kDhead;        // head's slice in q block
368	            const float* qrow = &sm->qkv[qi][qoff];   // [dhead]
369	            // scores over key positions kj<=qi (causal); softmax; ctx accum.
370	            float maxs = -CUDART_INF_F;
371	            float sc[dec::kSeq];
372	            #pragma unroll
373	            for (int kj = 0; kj < dec::kSeq; ++kj) {
374	                if (kj > qi) { sc[kj] = -CUDART_INF_F; continue; }
375	                const float* krow = &sm->qkv[kj][dec::kD + qoff];  // k block
376	                float dot = 0.0f;
377	                #pragma unroll
378	                for (int t = 0; t < dec::kDhead; ++t) dot += qrow[t] * krow[t];
379	                sc[kj] = dot * scale;
380	                maxs = fmaxf(maxs, sc[kj]);
381	            }
382	            float denom = 0.0f;
383	            #pragma unroll
384	            for (int kj = 0; kj < dec::kSeq; ++kj) {
385	                float e = (kj <= qi) ? __expf(sc[kj] - maxs) : 0.0f;
386	                sc[kj] = e; denom += e;
387	            }
388	            float invd = 1.0f / denom;
389	            // store attn weights (for bwd) + compute ctx slice for this (head,qi).
390	            #pragma unroll
391	            for (int kj = 0; kj < dec::kSeq; ++kj) {
392	                float a = sc[kj] * invd;
393	                sm->attn[hh][qi][kj] = a;
394	            }
395	            // ctx[qi, hh*dhead + t] = sum_kj attn * v[kj, hh*dhead+t]
396	            #pragma unroll
397	            for (int t = 0; t < dec::kDhead; ++t) {
398	                float acc = 0.0f;
399	                #pragma unroll
400	                for (int kj = 0; kj <= qi; ++kj) {
401	                    const float vv = sm->qkv[kj][2 * dec::kD + qoff + t];
402	                    acc += sm->attn[hh][qi][kj] * vv;
403	                }
404	                sm->ctx[qi][qoff + t] = acc;
405	            }
406	        }
407	        __syncthreads();
408	        // a = ctx @ out_w^T + out_b  (reuse qkv[:, :d] as the 'a' scratch).
409	        // We need a [kSeq,d]; write into sm->x1 temporarily then add residual.
410	        dec_linear(&sm->ctx[0][0], dec::kD, L.out_w, L.out_b, dec::kD,
411	                   &sm->x1[0][0]);   // x1 holds 'a' for now
412	        // r1 = hin + a ; n1(r1) -> x1 (overwrite). Stage r1 into ff0 scratch row.
413	        for (int idx = threadIdx.x; idx < dec::kSeq * dec::kD; idx += blockDim.x) {
414	            const int s = idx / dec::kD, j = idx % dec::kD;
415	            sm->ctx[s][j] = hin[s * dec::kD + j] + sm->x1[s][j];  // ctx := r1
416	        }
417	        __syncthreads();
418	        dec_layernorm_fwd(&sm->ctx[0][0], L.n1_w, L.n1_b, &sm->x1[0][0],
419	                          &sm->n1_xhat[0][0], &sm->n1_inv[0], sm->red);
420	        // FFN: ff0 = x1 @ ff0_w^T + ff0_b ; g = gelu(ff0) ; ff2 = g @ ff2_w^T+b.
421	        dec_linear(&sm->x1[0][0], dec::kD, L.ff0_w, L.ff0_b, dec::kDff,
422	                   &sm->ff0[0][0]);
423	        for (int idx = threadIdx.x; idx < dec::kSeq * dec::kDff; idx += blockDim.x)
424	            sm->gact[idx / dec::kDff][idx % dec::kDff] =
425	                dec_gelu(sm->ff0[idx / dec::kDff][idx % dec::kDff]);
426	        __syncthreads();
427	        // ff2 -> ctx scratch (reuse), then r2 = x1 + ff2, n2(r2) -> next layer_in.
428	        dec_linear(&sm->gact[0][0], dec::kDff, L.ff2_w, L.ff2_b, dec::kD,
429	                   &sm->ctx[0][0]);   // ctx := ff2
430	        for (int idx = threadIdx.x; idx < dec::kSeq * dec::kD; idx += blockDim.x) {
431	            const int s = idx / dec::kD, j = idx % dec::kD;
432	            sm->ctx[s][j] = sm->x1[s][j] + sm->ctx[s][j];   // ctx := r2
433	        }
434	        __syncthreads();
435	        // n2(r2) -> output of this layer. Destination: next layer's input cache,
436	        // or the final_in buffer if this is the last layer.
437	        float* dst = (li + 1 < dec::kLayers) ? &sm->layer_in[li + 1][0][0]
438	                                             : &sm->final_in[0][0];
439	        dec_layernorm_fwd(&sm->ctx[0][0], L.n2_w, L.n2_b, dst,
440	                          &sm->n2_xhat[0][0], &sm->n2_inv[0], sm->red);
441	    }
442	
443	    // Final norm on the LAST position only, then head → logits → NLL.
444	    // hn = norm(final_in[last]); logits = hn @ out_w^T + out_b.
445	    const float* hlast = &sm->final_in[dec::kSeq - 1][0];
446	    // LayerNorm of a single row (cooperative reduce).
447	    float sum = 0.0f;
448	    for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) sum += hlast[j];
449	    float mean = dec_block_sum(sum, sm->red) / (float)dec::kD;
450	    float vs = 0.0f;
451	    for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
452	        float c = hlast[j] - mean; vs += c * c;
453	    }
454	    float var = dec_block_sum(vs, sm->red) / (float)dec::kD;
455	    float inv = rsqrtf(var + dec::kLnEps);
456	    if (threadIdx.x == 0) sm->fn_inv[0] = inv;
457	    // Store hn into fn_xhat row 0's gamma/beta-applied value? We need both xhat
458	    // (for LN bwd) and hn (for head). Keep xhat in fn_xhat[last], compute hn into
459	    // x1 row 0 scratch.
460	    for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
461	        float xh = (hlast[j] - mean) * inv;
462	        sm->fn_xhat[dec::kSeq - 1][j] = xh;
463	        sm->x1[0][j] = xh * w.norm_w[j] + w.norm_b[j];   // x1[0] := hn
464	    }
465	    __syncthreads();
466	    // logits[o] = hn · out_w[o] + out_b[o]   (o over kVocab).
467	    for (int o = threadIdx.x; o < dec::kVocab; o += blockDim.x) {
468	        const float* Wr = w.out_w + (int64_t)o * dec::kD;
469	        float acc = w.out_b[o];
470	        #pragma unroll 4
471	        for (int k = 0; k < dec::kD; ++k) acc += sm->x1[0][k] * Wr[k];
472	        sm->logits[o] = acc;
473	    }
474	    __syncthreads();
475	    // NLL (mean handled by /B in the loss reduce): logz - logits[target].
476	    float lmax = -CUDART_INF_F;
477	    for (int o = threadIdx.x; o < dec::kVocab; o += blockDim.x)
478	        lmax = fmaxf(lmax, sm->logits[o]);
479	    lmax = dec_block_max(lmax, sm->red);
480	    float es = 0.0f;
481	    for (int o = threadIdx.x; o < dec::kVocab; o += blockDim.x)
482	        es += __expf(sm->logits[o] - lmax);
483	    es = dec_block_sum(es, sm->red);
484	    float logz = lmax + __logf(es);
485	    return logz - sm->logits[target];   // sample NLL
486	}
