488	// ── Atomic-free per-CTA grad accumulation. Each dW element has a SINGLE owner
489	//    thread within the CTA across the slice's samples, so a plain += into the
490	//    CTA's partial buffer is race-free AS LONG AS the same thread owns the same
491	//    element every sample. We guarantee that by always striding output elements
492	//    by threadIdx.x with the SAME total/stride, and __syncthreads() between
493	//    samples. acc_* helpers therefore use ordinary global +=. ─────────────────
494	
495	// Recompute one layer's forward intermediates into sm (qkv, x1, ff0, gact, attn,
496	// and ctx := r2), reading from sm->layer_in[li]. Mirrors the fwd layer body but
497	// also leaves r2 in sm->ctx and x1 in sm->x1 for the backward chain.
498	__device__ void dec_recompute_layer(const DecWeights& w, int li,
499	                                     DecSampleSmem* sm) {
500	    const DecWeights::Layer& L = w.layer[li];
501	    float* hin = &sm->layer_in[li][0][0];
502	    dec_linear(hin, dec::kD, L.in_w, L.in_b, 3 * dec::kD, &sm->qkv[0][0]);
503	    const float scale = dec::attn_scale();
504	    for (int r = threadIdx.x; r < dec::kHeads * dec::kSeq; r += blockDim.x) {
505	        const int hh = r / dec::kSeq, qi = r % dec::kSeq;
506	        const int qoff = hh * dec::kDhead;
507	        const float* qrow = &sm->qkv[qi][qoff];
508	        float maxs = -CUDART_INF_F; float sc[dec::kSeq];
509	        #pragma unroll
510	        for (int kj = 0; kj < dec::kSeq; ++kj) {
511	            if (kj > qi) { sc[kj] = -CUDART_INF_F; continue; }
512	            const float* krow = &sm->qkv[kj][dec::kD + qoff];
513	            float dot = 0.0f;
514	            #pragma unroll
515	            for (int t = 0; t < dec::kDhead; ++t) dot += qrow[t] * krow[t];
516	            sc[kj] = dot * scale; maxs = fmaxf(maxs, sc[kj]);
517	        }
518	        float denom = 0.0f;
519	        #pragma unroll
520	        for (int kj = 0; kj < dec::kSeq; ++kj) {
521	            float e = (kj <= qi) ? __expf(sc[kj] - maxs) : 0.0f;
522	            sc[kj] = e; denom += e;
523	        }
524	        float invd = 1.0f / denom;
525	        #pragma unroll
526	        for (int kj = 0; kj < dec::kSeq; ++kj) sm->attn[hh][qi][kj] = sc[kj] * invd;
527	        #pragma unroll
528	        for (int t = 0; t < dec::kDhead; ++t) {
529	            float acc = 0.0f;
530	            #pragma unroll
531	            for (int kj = 0; kj <= qi; ++kj)
532	                acc += sm->attn[hh][qi][kj] * sm->qkv[kj][2 * dec::kD + qoff + t];
533	            sm->ctx[qi][qoff + t] = acc;
534	        }
535	    }
536	    __syncthreads();
537	    // a -> x1 scratch, r1 -> separate; we need r1 for n1 bwd? n1 bwd needs xhat
538	    // (cached) + inv (cached); it does NOT need r1. So compute n1 fwd to fill
539	    // caches and leave x1 = n1(r1).
540	    dec_linear(&sm->ctx[0][0], dec::kD, L.out_w, L.out_b, dec::kD, &sm->x1[0][0]);
541	    for (int idx = threadIdx.x; idx < dec::kSeq * dec::kD; idx += blockDim.x) {
542	        const int s = idx / dec::kD, j = idx % dec::kD;
543	        sm->ctx[s][j] = hin[s * dec::kD + j] + sm->x1[s][j];   // ctx := r1
544	    }
545	    __syncthreads();
546	    dec_layernorm_fwd(&sm->ctx[0][0], L.n1_w, L.n1_b, &sm->x1[0][0],
547	                      &sm->n1_xhat[0][0], &sm->n1_inv[0], sm->red);  // x1 := n1(r1)
548	    dec_linear(&sm->x1[0][0], dec::kD, L.ff0_w, L.ff0_b, dec::kDff, &sm->ff0[0][0]);
549	    for (int idx = threadIdx.x; idx < dec::kSeq * dec::kDff; idx += blockDim.x) {
550	        const int s = idx / dec::kDff, j = idx % dec::kDff;
551	        sm->gact[s][j] = dec_gelu(sm->ff0[s][j]);
552	    }
553	    __syncthreads();
554	    // ff2 -> tmp, r2 = x1 + ff2 -> ctx (so ctx holds r2 for n2 bwd caches).
555	    // We use sm->ctx for r2; n2 caches (xhat/inv) are filled by the LN fwd below.
556	    // Stash ff2 in dh scratch (unused until bwd) to avoid clobbering x1.
557	    dec_linear(&sm->gact[0][0], dec::kDff, L.ff2_w, L.ff2_b, dec::kD, &sm->dh[0][0]);
558	    for (int idx = threadIdx.x; idx < dec::kSeq * dec::kD; idx += blockDim.x) {
559	        const int s = idx / dec::kD, j = idx % dec::kD;
560	        sm->ctx[s][j] = sm->x1[s][j] + sm->dh[s][j];   // ctx := r2
561	    }
562	    __syncthreads();
563	    // Fill n2 caches (we don't need n2's output value for bwd, only xhat/inv).
564	    // Write the (discarded) output into dh scratch.
565	    dec_layernorm_fwd(&sm->ctx[0][0], L.n2_w, L.n2_b, &sm->dh[0][0],
566	                      &sm->n2_xhat[0][0], &sm->n2_inv[0], sm->red);
567	    __syncthreads();
568	}
569	
570	// LayerNorm backward: given dy [kSeq,d] and cached (xhat,inv) for these
571	// positions, returns dx [kSeq,d] into dx_out, and ACCUMULATES dgamma/dbeta
572	// (summed over positions) into the CTA grad partials gw/gb [d]. Owner-thread
573	// rule for gw/gb: thread owns feature j (strided), sums over positions locally.
574	__device__ void dec_layernorm_bwd(
575	        const float* __restrict__ dy, const float* __restrict__ xhat,
576	        const float* __restrict__ inv, const float* __restrict__ gamma,
577	        float* __restrict__ dx_out, float* __restrict__ gw, float* __restrict__ gb,
578	        float* red, bool accum_affine) {
579	    // dgamma/dbeta: feature-parallel, sum over positions (single owner per j).
580	    if (accum_affine) {
581	        for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
582	            float dgw = 0.0f, dgb = 0.0f;
583	            #pragma unroll
584	            for (int s = 0; s < dec::kSeq; ++s) {
585	                float d = dy[s * dec::kD + j];
586	                dgb += d; dgw += d * xhat[s * dec::kD + j];
587	            }
588	            gw[j] += dgw; gb[j] += dgb;
589	        }
590	    }
591	    // dx per position: needs sum(dxhat) and sum(dxhat*xhat) over d (reduce).
592	    for (int s = 0; s < dec::kSeq; ++s) {
593	        const float* dyr = dy + s * dec::kD;
594	        const float* xhr = xhat + s * dec::kD;
595	        float sda = 0.0f, sdax = 0.0f;
596	        for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
597	            float dxhat = dyr[j] * gamma[j];
598	            sda += dxhat; sdax += dxhat * xhr[j];
599	        }
600	        sda = dec_block_sum(sda, red);
601	        sdax = dec_block_sum(sdax, red);
602	        float inv_s = inv[s];
603	        for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
604	            float dxhat = dyr[j] * gamma[j];
605	            dx_out[s * dec::kD + j] =
606	                inv_s * (dxhat - (sda + xhr[j] * sdax) / (float)dec::kD);
607	        }
608	        __syncthreads();
609	    }
610	}
611	
612	// dW += dY^T @ X  for a linear Y = X @ W^T + b. dY [kSeq,out], X [kSeq,in],
613	// dW [out,in]. Owner-thread rule: thread owns (o,i) output element (strided over
614	// out*in), sums over the kSeq positions locally. db[o] += sum_s dY[s,o].
615	// Also returns dX [kSeq,in] += dY @ W into dx_out (caller decides add vs set).
616	//
617	// ldY/ldX/ldDX are the ROW STRIDES (leading dimensions) of dY/X/dx_out. They
618	// are EXPLICIT (no defaults) because the smem scratch buffers this is called on
619	// are 2D arrays whose declared width (e.g. kDff=512 for ff0/gact) differs from
620	// the logical row width (out_dim/in_dim). The original packed-stride version
621	// silently read/wrote the wrong rows at both attention-seam call sites — the
622	// forward stayed exact while every grad upstream of attention was garbage
623	// (params decayed to zero via weight decay; train acc pinned at 1/97). The CPU
624	// structural mirror did NOT catch it (it indexes buffers semantically, not by
625	// flat offset), so the stride is now part of the call contract.
626	__device__ void dec_linear_bwd(
627	        const float* __restrict__ dY, const float* __restrict__ X,
628	        const float* __restrict__ W, int in_dim, int out_dim,
629	        float* __restrict__ dW, float* __restrict__ db,
630	        float* __restrict__ dx_out, bool set_dx,
631	        int ldY, int ldX, int ldDX) {
632	    // dW [out,in] + db [out].
633	    const int wtot = out_dim * in_dim;
634	    for (int idx = threadIdx.x; idx < wtot; idx += blockDim.x) {
635	        const int o = idx / in_dim, i = idx % in_dim;
636	        float acc = 0.0f;
637	        #pragma unroll
638	        for (int s = 0; s < dec::kSeq; ++s)
639	            acc += dY[s * ldY + o] * X[s * ldX + i];
640	        dW[(int64_t)o * in_dim + i] += acc;
641	    }
642	    if (db != nullptr) {
643	        for (int o = threadIdx.x; o < out_dim; o += blockDim.x) {
644	            float acc = 0.0f;
645	            #pragma unroll
646	            for (int s = 0; s < dec::kSeq; ++s) acc += dY[s * ldY + o];
647	            db[o] += acc;
648	        }
649	    }
650	    // dX [kSeq,in] = dY @ W  (W [out,in]).
651	    const int xtot = dec::kSeq * in_dim;
652	    for (int idx = threadIdx.x; idx < xtot; idx += blockDim.x) {
653	        const int s = idx / in_dim, i = idx % in_dim;
654	        float acc = 0.0f;
655	        for (int o = 0; o < out_dim; ++o)
656	            acc += dY[s * ldY + o] * W[(int64_t)o * in_dim + i];
657	        if (set_dx) dx_out[s * ldDX + i] = acc;
658	        else dx_out[s * ldDX + i] += acc;
659	    }
660	    __syncthreads();
661	}
662	
663	// ────────────────────────────────────────────────────────────────────────────
664	//  BACKWARD for one sample (CTA-cooperative). Assumes dec_forward_sample has run
665	//  for THIS sample (so layer_in/final_in/fn caches/logits are populated and
666	//  reflect this sample). Accumulates every weight grad into the CTA's partial
667	//  buffer `g` (DecGrad over gw_cta). Uses extra smem scratch passed via sm.
668	//
669	//  Transcribed from tests/hw/decoder_oracle.py::decoder_backward.
670	// ────────────────────────────────────────────────────────────────────────────
671	__device__ void dec_backward_sample(const DecWeights& w, const DecGrad& g,
672	                                     const int* tokens_s, int target, int B,
673	                                     DecSampleSmem* sm) {
674	    // ── CE backward: dlogits = (softmax - onehot)/B. (logits cached in fwd.) ──
675	    float lmax = -CUDART_INF_F;
676	    for (int o = threadIdx.x; o < dec::kVocab; o += blockDim.x)
677	        lmax = fmaxf(lmax, sm->logits[o]);
678	    lmax = dec_block_max(lmax, sm->red);
679	    float es = 0.0f;
680	    for (int o = threadIdx.x; o < dec::kVocab; o += blockDim.x)
681	        es += __expf(sm->logits[o] - lmax);
682	    es = dec_block_sum(es, sm->red);
683	    float inv_es = 1.0f / es;
684	    // overwrite logits[] with dlogits in place.
685	    for (int o = threadIdx.x; o < dec::kVocab; o += blockDim.x) {
686	        float sm_o = __expf(sm->logits[o] - lmax) * inv_es;
687	        float dl = (sm_o - ((o == target) ? 1.0f : 0.0f)) / (float)B;
688	        sm->logits[o] = dl;
689	    }
690	    __syncthreads();
691	    // ── head (out): logits = hn @ out_w^T + out_b. hn was stashed in x1[0]
692	    //    during fwd, but x1 has since been reused — recompute hn from the
693	    //    cached final-norm: hn[j] = fn_xhat[last][j]*norm_w[j] + norm_b[j]. ──
694	    // dW_out[o,:] += dlogits[o] * hn ; db_out[o] += dlogits[o].
695	    // dhn[j] = sum_o dlogits[o] * out_w[o,j].
696	    for (int o = threadIdx.x; o < dec::kVocab; o += blockDim.x) {
697	        float dl = sm->logits[o];
698	        g.out_b[o] += dl;
699	        float* gwrow = g.out_w + (int64_t)o * dec::kD;
700	        const float* xh = &sm->fn_xhat[dec::kSeq - 1][0];
701	        #pragma unroll 4
702	        for (int j = 0; j < dec::kD; ++j) {
703	            float hn_j = xh[j] * w.norm_w[j] + w.norm_b[j];
704	            gwrow[j] += dl * hn_j;
705	        }
706	    }
707	    __syncthreads();
708	    // dhn[j] (feature-parallel) into dh row 0 scratch.
709	    for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
710	        float acc = 0.0f;
711	        for (int o = 0; o < dec::kVocab; ++o)
712	            acc += sm->logits[o] * w.out_w[(int64_t)o * dec::kD + j];
713	        sm->dh[0][j] = acc;   // dhn
714	    }
715	    __syncthreads();
716	    // ── final norm backward: dy=dhn (row last), xhat=fn_xhat[last], inv=fn_inv.
717	    //    Produces dh_last into dh[last]; accumulate dnorm_w/dnorm_b. Use a single
718	    //    "position" (last). Build a 1-row dy view: reuse sm->ctx row last = dhn. ─
719	    for (int j = threadIdx.x; j < dec::kD; j += blockDim.x)
720	        sm->ctx[dec::kSeq - 1][j] = sm->dh[0][j];   // dy at last position
721	    __syncthreads();
722	    // dnorm_w/dnorm_b: only the last position contributes (others have dy=0).
723	    for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
724	        float d = sm->ctx[dec::kSeq - 1][j];
725	        float xh = sm->fn_xhat[dec::kSeq - 1][j];
726	        g.norm_b[j] += d; g.norm_w[j] += d * xh;
727	    }
728	    __syncthreads();
729	    // dx for the last position (LN backward, single row).
730	    {
731	        const float* dyr = &sm->ctx[dec::kSeq - 1][0];
732	        const float* xhr = &sm->fn_xhat[dec::kSeq - 1][0];
733	        float sda = 0.0f, sdax = 0.0f;
734	        for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
735	            float dxhat = dyr[j] * w.norm_w[j];
736	            sda += dxhat; sdax += dxhat * xhr[j];
737	        }
738	        sda = dec_block_sum(sda, sm->red);
739	        sdax = dec_block_sum(sdax, sm->red);
740	        float inv_s = sm->fn_inv[0];
741	        for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
742	            float dxhat = dyr[j] * w.norm_w[j];
743	            // dh[s,:] = 0 for s<last; last gets the LN dx.
744	            for (int s = 0; s < dec::kSeq; ++s) sm->dh[s][j] = 0.0f;
745	            sm->dh[dec::kSeq - 1][j] =
746	                inv_s * (dxhat - (sda + xhr[j] * sdax) / (float)dec::kD);
747	        }
748	        __syncthreads();
749	    }
750	    // dh now = grad wrt the last layer's OUTPUT [kSeq,d] (only last pos nonzero).
751	
752	    // ── per-layer backward (reverse). Each layer: recompute fwd intermediates,
753	    //    then apply the chain. We use sm scratch heavily; the running adjoint
754	    //    `dh` is preserved across the recompute (recompute writes qkv/x1/ff0/
755	    //    gact/attn/ctx + LN caches; it temporarily uses sm->dh as ff2 scratch —
756	    //    so SAVE dh into final_in (free after fwd) around the recompute). ───────
757	    for (int li = dec::kLayers - 1; li >= 0; --li) {
758	        const DecWeights::Layer& L = w.layer[li];
759	        const DecGrad::Layer& G = g.layer[li];
760	        // Save the incoming adjoint dh into final_in (unused now) — recompute
761	        // clobbers sm->dh.
762	        for (int idx = threadIdx.x; idx < dec::kSeq * dec::kD; idx += blockDim.x) {
763	            const int s = idx / dec::kD, j = idx % dec::kD;
764	            sm->final_in[s][j] = sm->dh[s][j];
765	        }
766	        __syncthreads();
767	        dec_recompute_layer(w, li, sm);   // fills qkv,x1,ff0,gact,attn,ctx(=r2),caches
768	        // Restore dh (grad wrt h2 = n2 output).
769	        for (int idx = threadIdx.x; idx < dec::kSeq * dec::kD; idx += blockDim.x) {
770	            const int s = idx / dec::kD, j = idx % dec::kD;
771	            sm->dh[s][j] = sm->final_in[s][j];
772	        }
773	        __syncthreads();
774	        // n2 backward: dh -> dr2, accumulate n2 gamma/beta. Put dr2 into ctx
775	        // (currently r2 — we no longer need r2's value, only its caches).
776	        dec_layernorm_bwd(&sm->dh[0][0], &sm->n2_xhat[0][0], &sm->n2_inv[0],
777	                          L.n2_w, &sm->ctx[0][0], G.n2_w, G.n2_b, sm->red, true);
778	        // r2 = x1 + ff2 → both branches get dr2: dx1 (residual) and dff2.
779	        // SMEM map (one layer live; values consumed before each reuse — verified
780	        // alias-safe by the structural mirror): dx1 lives in `fn_xhat` (final-norm
781	        // caches are done), dr2 stays in `ctx`. x_in = layer_in[li] is NOT touched
782	        // (in_proj bwd needs it); qkv is NOT touched (attention bwd needs q/k/v).
783	        for (int idx = threadIdx.x; idx < dec::kSeq * dec::kD; idx += blockDim.x) {
784	            const int s = idx / dec::kD, j = idx % dec::kD;
785	            sm->fn_xhat[s][j] = sm->ctx[s][j];   // dx1 := dr2 (residual part)
786	        }
787	        __syncthreads();
788	        // ff.2 backward. dgact = dr2 @ ff2_w is needed only to form
789	        // dff0 = dgact * gelu'(ff0); since `ff0` (pre-gelu) is needed for gelu'(),
790	        // we compute dgact and immediately fold gelu' so dff0 is written OVER
791	        // `gact` (its forward value g is consumed by the dW_ff2 GEMM first). No
792	        // extra scratch buffer is needed.
793	        //   dW_ff2 += dr2^T @ g ; db_ff2 += Σ dr2.
794	        {
795	            const float* dY = &sm->ctx[0][0];   // dr2 [kSeq,d]
796	            const float* X = &sm->gact[0][0];   // g [kSeq,4d]
797	            // dW ff2 [d,4d]
798	            const int wtot = dec::kD * dec::kDff;
799	            for (int idx = threadIdx.x; idx < wtot; idx += blockDim.x) {
800	                const int o = idx / dec::kDff, i = idx % dec::kDff;
801	                float acc = 0.0f;
802	                #pragma unroll
803	                for (int s = 0; s < dec::kSeq; ++s)
804	                    acc += dY[s * dec::kD + o] * X[s * dec::kDff + i];
805	                G.ff2_w[(int64_t)o * dec::kDff + i] += acc;
806	            }
807	            for (int o = threadIdx.x; o < dec::kD; o += blockDim.x) {
808	                float acc = 0.0f;
809	                #pragma unroll
810	                for (int s = 0; s < dec::kSeq; ++s) acc += dY[s * dec::kD + o];
811	                G.ff2_b[o] += acc;
812	            }
813	            __syncthreads();
814	            // dff0 = (dr2 @ ff2_w) * gelu'(ff0), written OVER gact.
815	            const int xtot = dec::kSeq * dec::kDff;
816	            for (int idx = threadIdx.x; idx < xtot; idx += blockDim.x) {
817	                const int s = idx / dec::kDff, i = idx % dec::kDff;
818	                float dg = 0.0f;
819	                for (int o = 0; o < dec::kD; ++o)
820	                    dg += dY[s * dec::kD + o] * L.ff2_w[(int64_t)o * dec::kDff + i];
821	                sm->gact[s][i] = dg * dec_gelu_grad(sm->ff0[s][i]);  // gact := dff0
822	            }
823	            __syncthreads();
824	        }
825	        // ff.0 backward: dY=dff0 (=gact), X=x1 -> dW ff0, db ff0, dx1 += dff0 @ ff0_w.
826	        // dx1 currently in fn_xhat (residual part); ADD the FFN path.
827	        {
828	            const float* dY = &sm->gact[0][0];   // dff0 [kSeq,4d]
829	            const float* X = &sm->x1[0][0];      // x1 [kSeq,d]
830	            const int wtot = dec::kDff * dec::kD;
831	            for (int idx = threadIdx.x; idx < wtot; idx += blockDim.x) {
832	                const int o = idx / dec::kD, i = idx % dec::kD;
833	                float acc = 0.0f;
834	                #pragma unroll
835	                for (int s = 0; s < dec::kSeq; ++s)
836	                    acc += dY[s * dec::kDff + o] * X[s * dec::kD + i];
837	                G.ff0_w[(int64_t)o * dec::kD + i] += acc;
838	            }
839	            for (int o = threadIdx.x; o < dec::kDff; o += blockDim.x) {
840	                float acc = 0.0f;
841	                #pragma unroll
842	                for (int s = 0; s < dec::kSeq; ++s) acc += dY[s * dec::kDff + o];
843	                G.ff0_b[o] += acc;
844	            }
845	            __syncthreads();
846	            const int xtot = dec::kSeq * dec::kD;
847	            for (int idx = threadIdx.x; idx < xtot; idx += blockDim.x) {
848	                const int s = idx / dec::kD, i = idx % dec::kD;
849	                float acc = 0.0f;
850	                for (int o = 0; o < dec::kDff; ++o)
851	                    acc += dY[s * dec::kDff + o] * L.ff0_w[(int64_t)o * dec::kD + i];
852	                sm->fn_xhat[s][i] += acc;   // dx1 += FFN path
853	            }
854	            __syncthreads();
855	        }
856	        // dx1 (in fn_xhat) -> n1 backward -> dr1 (into ctx). accumulate n1 g/b.
857	        dec_layernorm_bwd(&sm->fn_xhat[0][0], &sm->n1_xhat[0][0], &sm->n1_inv[0],
858	                          L.n1_w, &sm->ctx[0][0], G.n1_w, G.n1_b, sm->red, true);
859	        // r1 = x_in + a -> da = dr1 ; dx_in = dr1 (residual). dx_in accumulates
860	        // both the residual AND the attention-input path; stash dx_in into
861	        // fn_xhat (free again). da stays in ctx.
862	        for (int idx = threadIdx.x; idx < dec::kSeq * dec::kD; idx += blockDim.x) {
863	            const int s = idx / dec::kD, j = idx % dec::kD;
864	            sm->fn_xhat[s][j] = sm->ctx[s][j];   // dx_in := dr1 (residual)
865	        }
866	        __syncthreads();
867	        // attn out_proj backward: a = ctx_fwd @ out_w^T + out_b. But ctx_fwd
868	        // (the attention context) was overwritten by the recompute's r1/r2 reuse.
869	        // Recompute ctx_fwd from attn + v (cheap): we still have attn[] and qkv[]
870	        // (v lives in qkv[:,2d:3d]). Rebuild ctx_fwd into x1 scratch (x1 no longer
871	        // needed — ff bwd done).
872	        for (int r = threadIdx.x; r < dec::kSeq * dec::kD; r += blockDim.x) {
873	            const int qi = r / dec::kD, col = r % dec::kD;
874	            const int hh = col / dec::kDhead, t = col % dec::kDhead;
875	            float acc = 0.0f;
876	            #pragma unroll
877	            for (int kj = 0; kj <= qi; ++kj)
878	                acc += sm->attn[hh][qi][kj]
879	                     * sm->qkv[kj][2 * dec::kD + hh * dec::kDhead + t];
880	            sm->x1[qi][col] = acc;   // x1 := ctx_fwd
881	        }
882	        __syncthreads();
883	        // da is in ctx. dW_out += da^T @ ctx_fwd(x1); db_out += sum da;
884	        // dctx = da @ out_w -> store into ff0 scratch (free). dctx MUST be
885	        // written at ff0's DECLARED row stride (kDff) — passes A/B below read it
886	        // as sm->ff0[qi][col]; a packed (kD-stride) write only fills row 0's
887	        // first 512 floats and rows 1..3 read stale recomputed pre-GELU values.
888	        dec_linear_bwd(&sm->ctx[0][0], &sm->x1[0][0], L.out_w, dec::kD, dec::kD,
889	                       G.out_w, G.out_b, &sm->ff0[0][0], /*set_dx=*/true, // dctx->ff0
890	                       /*ldY=*/dec::kD, /*ldX=*/dec::kD, /*ldDX=*/dec::kDff);
891	        // ── merge-heads + attention backward (3 synced passes; the forward
892	        //    softmax weights `attn` are read by A and B and NEVER overwritten —
893	        //    dscores go to the dedicated `dsc` buffer). dctx [kSeq,d] is in ff0;
894	        //    v lives in qkv[:,2d:3d], k in qkv[:,d:2d], q in qkv[:,0:d]. dqkv is
895	        //    built into gact[:, :3d]. Transcribed from the oracle's attention bwd:
896	        //      dvh   = attn^T @ dctxh
897	        //      dattn = dctxh @ vh^T ; dscores = softmax_bwd(dattn,attn) * scale
898	        //      dqh   = dscores @ kh ; dkh = dscores^T @ qh                       ─
899	        const float scale = dec::attn_scale();
900	        // A: dv into gact[:, 2d:3d].  dv[kj,qoff+t] = Σ_{qi>=kj} attn[hh][qi][kj]
901	        //    * dctx[qi, qoff+t].  (Owner: thread per (kj, head, t).)
902	        for (int r = threadIdx.x; r < dec::kSeq * dec::kHeads * dec::kDhead;
903	             r += blockDim.x) {
904	            const int kj = r / (dec::kHeads * dec::kDhead);
905	            const int rem = r % (dec::kHeads * dec::kDhead);
906	            const int hh = rem / dec::kDhead, t = rem % dec::kDhead;
907	            const int qoff = hh * dec::kDhead;
908	            float acc = 0.0f;
909	            #pragma unroll
910	            for (int qi = kj; qi < dec::kSeq; ++qi)   // qi>=kj (causal: kj<=qi)
911	                acc += sm->attn[hh][qi][kj] * sm->ff0[qi][qoff + t];
912	            sm->gact[kj][2 * dec::kD + qoff + t] = acc;   // dv block
913	        }
914	        __syncthreads();
915	        // B: dscores into dsc.  datt[hh,qi,kj] = Σ_t dctx[qi,qoff+t]*v[kj,qoff+t];
916	        //    ds = attn*(datt - Σ_k datt*attn)*scale  (masked kj>qi → 0).
917	        for (int r = threadIdx.x; r < dec::kHeads * dec::kSeq; r += blockDim.x) {
918	            const int hh = r / dec::kSeq, qi = r % dec::kSeq;
919	            const int qoff = hh * dec::kDhead;
920	            float datt[dec::kSeq];
921	            #pragma unroll
922	            for (int kj = 0; kj < dec::kSeq; ++kj) {
923	                if (kj > qi) { datt[kj] = 0.0f; continue; }
924	                float acc = 0.0f;
925	                #pragma unroll
926	                for (int t = 0; t < dec::kDhead; ++t)
927	                    acc += sm->ff0[qi][qoff + t]
928	                         * sm->qkv[kj][2 * dec::kD + qoff + t];
929	                datt[kj] = acc;
930	            }
931	            float dot = 0.0f;
932	            #pragma unroll
933	            for (int kj = 0; kj <= qi; ++kj) dot += datt[kj] * sm->attn[hh][qi][kj];
934	            #pragma unroll
935	            for (int kj = 0; kj < dec::kSeq; ++kj) {
936	                float a = sm->attn[hh][qi][kj];
937	                sm->dsc[hh][qi][kj] = (kj <= qi) ? a * (datt[kj] - dot) * scale
938	                                                 : 0.0f;
939	            }
940	        }
941	        __syncthreads();
942	        // C: dq into gact[:,0:d], dk into gact[:,d:2d].
943	        //    dq[qi,qoff+t] = Σ_kj dsc[hh][qi][kj]*k[kj,qoff+t];
944	        //    dk[kj,qoff+t] = Σ_qi dsc[hh][qi][kj]*q[qi,qoff+t].  (Owner: pos,head,t.)
945	        for (int r = threadIdx.x; r < dec::kSeq * dec::kHeads * dec::kDhead;
946	             r += blockDim.x) {
947	            const int pos = r / (dec::kHeads * dec::kDhead);
948	            const int rem = r % (dec::kHeads * dec::kDhead);
949	            const int hh = rem / dec::kDhead, t = rem % dec::kDhead;
950	            const int qoff = hh * dec::kDhead;
951	            float dq = 0.0f, dk = 0.0f;
952	            #pragma unroll
953	            for (int kj = 0; kj < dec::kSeq; ++kj) {
954	                dq += sm->dsc[hh][pos][kj] * sm->qkv[kj][dec::kD + qoff + t];
955	                dk += sm->dsc[hh][kj][pos] * sm->qkv[kj][qoff + t];
956	            }
957	            sm->gact[pos][qoff + t] = dq;            // dq block (gact[:,0:d])
958	            sm->gact[pos][dec::kD + qoff + t] = dk;  // dk block (gact[:,d:2d])
959	        }
960	        __syncthreads();
961	        // in_proj backward: dqkv (gact[:, :3d]) -> dW in, db in, dx_in += dqkv @ in_w.
962	        // x_in = layer_in[li]. dqkv was written 2D (sm->gact[pos][col]) so dY's
963	        // row stride is gact's DECLARED width kDff — a packed (3d=384) read
964	        // walks off row 0 into the stale dff0 values left in gact[0][384:512].
965	        dec_linear_bwd(&sm->gact[0][0], &sm->layer_in[li][0][0], L.in_w,
966	                       dec::kD, 3 * dec::kD, G.in_w, G.in_b,
967	                       &sm->fn_xhat[0][0], /*set_dx=*/false,   // dx_in += attn path
968	                       /*ldY=*/dec::kDff, /*ldX=*/dec::kD, /*ldDX=*/dec::kD);
969	        // dh for the previous layer = dx_in (in fn_xhat). Move to dh.
970	        for (int idx = threadIdx.x; idx < dec::kSeq * dec::kD; idx += blockDim.x) {
971	            const int s = idx / dec::kD, j = idx % dec::kD;
972	            sm->dh[s][j] = sm->fn_xhat[s][j];
973	        }
974	        __syncthreads();
975	    }
976	
977	    // ── embedding backward: dh = grad wrt h0 [kSeq,d]. tok scatter-add per token
978	    //    id; pos sum over the sample's positions. Owner-thread rule: thread owns
979	    //    column j; loops positions SEQUENTIALLY so colliding token ids accumulate
980	    //    deterministically (mirrors the oracle's index_add_). ──────────────────
981	    for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
982	        #pragma unroll
983	        for (int s = 0; s < dec::kSeq; ++s) {
984	            float d = sm->dh[s][j];
985	            g.tok[(int64_t)tokens_s[s] * dec::kD + j] += d;   // single owner: col j
986	            g.pos[(int64_t)s * dec::kD + j] += d;
987	        }
988	    }
989	    __syncthreads();
990	}
