template <int N>
__global__ void __launch_bounds__(256)
gemm_fwd_kernel(const __nv_bfloat16* __restrict__ X,   // [M, Kin] row-major
                const __nv_bfloat16* __restrict__ W,   // [N, Kin] row-major (Nout=N)
                float* __restrict__ D,                 // [M, N] row-major out
                int Kin) {
#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 900)
    extern __shared__ __nv_bfloat16 smem[];
    __nv_bfloat16* sA = smem;
    __nv_bfloat16* sB = sA + 64 * 16;          // A is 64x16
    const int M = dectc::kTileM;
    const int k_steps = Kin / 16;
    // (fwd) Y[m,n] = Σ_k X[m,k]·W[n,k]. A=X (m,k), B=W (n,k). No transpose.
    auto srcA = [&] (int m, int k) -> __nv_bfloat16 { return X[(int64_t)m * Kin + k]; };
    auto srcB = [&] (int n, int k) -> __nv_bfloat16 { return W[(int64_t)n * Kin + k]; };
    auto out  = [&] (int m, int n, float v) { if (m < M) D[(int64_t)m * N + n] = v; };
    dectc::tc_gemm_tile_unpipelined<N>(k_steps, srcA, srcB, out, sA, sB);
#else
    (void)X; (void)W; (void)D; (void)Kin;
#endif
}

